-- Worst score is the discard. When several races share it, the latest one is discarded.
do $$
declare
  bad integer;
begin
  select count(*) into bad
  from csc2025 row
  where jsonb_array_length(row.races) <> case when row.fleet = 'Silver' then 7 else 6 end
     or (select count(*) from jsonb_array_elements(row.races) item where (item->>'discarded')::boolean) <> 1
     or (select sum((item->>'score')::real) from jsonb_array_elements(row.races) item) <> row.total
     or (select sum((item->>'score')::real) from jsonb_array_elements(row.races) item where not (item->>'discarded')::boolean) <> row.nett;
  if bad <> 0 or (select count(*) from csc2025 where fleet = 'Silver') <> 62
     or (select count(*) from csc2025 where fleet = 'Gold') <> 84 then
    raise exception 'CSC 2025 result sheet failed score checks: bad %, silver %, gold %',
      bad,
      (select count(*) from csc2025 where fleet = 'Silver'),
      (select count(*) from csc2025 where fleet = 'Gold');
  end if;
end $$;

update csc2025 source
set sailor_id = picked.id
from (
  select pdf.fleet, pdf.pos, existing.id
  from csc2025 pdf
  join public.regatta_results result on abs(result.nett_score - pdf.nett) < 0.01
  join public.regattas regatta on regatta.id = result.regatta_id
    and regatta.slug = case pdf.fleet
      when 'Silver' then 'csc-silver-jan-25-2025-01-18'
      else 'csc-gold-jan-25-2025-01-25'
    end
  join public.sailors existing on existing.id = result.sailor_id
  where (
    select count(*) from regexp_split_to_table(
      trim(regexp_replace(lower(replace(replace(replace(pdf.pdf_name, 'Xaiver', 'Xavier'), 'Sit Raidah', 'Siti Raidah'), 'Mohd Shahrom', 'Mohamed Shahrom')), '[^a-z0-9]+', ' ', 'g')),
      ' '
    ) tok
    where tok <> '' and tok not in ('bin', 'binte', 'binti', 'mohd')
      and (' ' || regexp_replace(lower(replace(existing.name, 'Gagliard ', 'Gagliardi ')), '[^a-z0-9]+', ' ', 'g') || ' ') like ('% ' || tok || ' %')
  ) = (
    select count(*) from regexp_split_to_table(
      trim(regexp_replace(lower(replace(replace(replace(pdf.pdf_name, 'Xaiver', 'Xavier'), 'Sit Raidah', 'Siti Raidah'), 'Mohd Shahrom', 'Mohamed Shahrom')), '[^a-z0-9]+', ' ', 'g')),
      ' '
    ) tok
    where tok <> '' and tok not in ('bin', 'binte', 'binti', 'mohd')
  )
) picked
where source.fleet = picked.fleet and source.pos = picked.pos;

update csc2025 set sailor_id = '20a011f0-320f-4c70-86e4-660de7a7438e' where fleet = 'Gold' and pos = 20;
