do $$
declare
  missing integer;
  distinct_sailors integer;
begin
  select count(*) into missing from csc2025 where sailor_id is null;
  select count(distinct sailor_id) into distinct_sailors from csc2025;
  if missing <> 0 or distinct_sailors <> 146 then
    raise exception 'CSC 2025 sailor match failed: missing %, distinct %', missing, distinct_sailors;
  end if;
end $$;

insert into public.regatta_events (
  name, slug, start_date, end_date, venue, organizer, classes,
  counts_for_ranking, is_selection_trial, created_at, updated_at
) values (
  'CSC Optimist Championships 2025',
  'csc-optimist-championships-2025',
  '2025-01-18',
  '2025-01-26',
  'Changi Sailing Club, 32 Netheravon Road, Singapore 508508',
  'Changi Sailing Club',
  '["Optimist Gold", "Optimist Silver"]'::jsonb,
  true,
  false,
  now(),
  now()
)
on conflict (slug) do update set
  name = excluded.name,
  start_date = excluded.start_date,
  end_date = excluded.end_date,
  venue = excluded.venue,
  organizer = excluded.organizer,
  classes = excluded.classes,
  updated_at = now();

update public.regattas regatta
set event_id = event.id,
    name = case regatta.division
      when 'Silver' then 'CSC Optimist Championships 2025 (Optimist Silver)'
      else 'CSC Optimist Championships 2025 (Optimist Gold)'
    end,
    end_date = case regatta.division when 'Silver' then '2025-01-19'::date else '2025-01-26'::date end,
    race_count = case regatta.division when 'Silver' then 7 else 6 end,
    total_fleet_size = case regatta.division when 'Silver' then 62 else 84 end,
    geography = 'SGP',
    venue = 'Changi Sailing Club, 32 Netheravon Road, Singapore 508508',
    organizer = 'Changi Sailing Club',
    schedule_notes = case regatta.division
      when 'Silver' then 'CSC Optimist Championship Silver Fleet, 18-19 January 2025. Seven races completed; best six count. Provisional results 19 January 2025.'
      else 'CSC Optimist Championship Gold Fleet, 25-26 January 2025. Six races completed; best five count. Provisional results 26 January 2025.'
    end,
    counts_for_ranking = true,
    status = 'published',
    updated_at = now()
from public.regatta_events event
where event.slug = 'csc-optimist-championships-2025'
  and regatta.slug in ('csc-silver-jan-25-2025-01-18', 'csc-gold-jan-25-2025-01-25');

delete from public.regatta_results result
using public.regattas regatta
where result.regatta_id = regatta.id
  and regatta.slug in ('csc-silver-jan-25-2025-01-18', 'csc-gold-jan-25-2025-01-25');

insert into public.regatta_results (
  sailor_id, regatta_id, rank, nett_score, total_score, is_dns, is_overseas_commitment,
  gender, nationality, birth_year, evidence_name, evidence_type, evidence_notes,
  verification_status, verified_at, created_at, updated_at
)
select
  source.sailor_id,
  regatta.id,
  source.final_rank,
  source.nett,
  source.total,
  false,
  false,
  source.sex,
  sailor.nationality,
  extract(year from sailor.dob)::integer,
  case source.fleet
    when 'Silver' then 'CSC Optimist Championship (Silver) 2025 provisional results.pdf'
    else 'CSC Optimist Championship (Gold) 2025 provisional results.pdf'
  end,
  'pdf',
  case source.fleet
    when 'Silver' then 'Official PowerScore provisional results, 19 January 2025. Seven races, one discard.'
    else 'Official PowerScore provisional results, 26 January 2025. Six races, one discard.'
  end,
  'verified',
  now(),
  now(),
  now()
from csc2025 source
join public.sailors sailor on sailor.id = source.sailor_id
join public.regattas regatta on regatta.slug = case source.fleet
  when 'Silver' then 'csc-silver-jan-25-2025-01-18'
  else 'csc-gold-jan-25-2025-01-25'
end;

insert into public.regatta_race_results (
  regatta_result_id, race_number, score, scoring_code, discarded, raw_value, created_at, updated_at
)
select
  result.id,
  race.ordinality::integer,
  (race.item->>'score')::real,
  nullif(race.item->>'code', ''),
  (race.item->>'discarded')::boolean,
  race.item->>'raw',
  now(),
  now()
from csc2025 source
join public.regattas regatta on regatta.slug = case source.fleet
  when 'Silver' then 'csc-silver-jan-25-2025-01-18'
  else 'csc-gold-jan-25-2025-01-25'
end
join public.regatta_results result on result.regatta_id = regatta.id and result.sailor_id = source.sailor_id
cross join lateral jsonb_array_elements(source.races) with ordinality as race(item, ordinality);

update public.sailors sailor
set gender = source.sex, updated_at = now()
from csc2025 source
where sailor.id = source.sailor_id and sailor.gender is null;
